public class MainActivity extends Activity {
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final ExecutorService loader=Executors.newSingleThreadExecutor();
    private final ArrayList<JSONObject> meetings=new ArrayList<>();
    private LinearLayout root,content;private TextView state,timer;private RecordingOrbView orb;
    private String page="Meetings",error;private boolean visible,indexBusy,indexReady,startPending,finishing,sheetOpen;
    private int open,drafts,unavailable;private long timerBase=-1,startRequestUtc;private String recordingId;
    private final HashSet<String> beforeStart=new HashSet<>();
    private final Runnable poll=new Runnable(){public void run(){if(!visible)return;updateCapture();handler.postDelayed(this,500);}};
    @Override public void onCreate(Bundle b){super.onCreate(b);if(b!=null){page=b.getString("page","Meetings");finishing=b.getBoolean("finishing");startPending=b.getBoolean("startPending");startRequestUtc=b.getLong("startRequestUtc");recordingId=b.getString("recordingId");for(String id:b.getStringArrayList("beforeStart")==null?new ArrayList<String>():b.getStringArrayList("beforeStart"))beforeStart.add(id);}if(b!=null&&"Record".equals(page))page="Meetings";getWindow().setStatusBarColor(PopUi.PAPER);getWindow().setNavigationBarColor(PopUi.PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);handleIncomingIntent(getIntent(),b!=null);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleIncomingIntent(intent,false);}
    private void handleIncomingIntent(Intent intent,boolean restored){
        String target=intent==null?null:intent.getStringExtra("popPage");
        String token=intent==null?null:intent.getStringExtra(RecordEntryGuard.EXTRA_TOKEN);
        // Never retain a capability in the Activity intent across recreation.
        if(intent!=null)intent.removeExtra(RecordEntryGuard.EXTRA_TOKEN);
        boolean permitted=RecordEntryGuard.INSTANCE.allowRecord(target,token,restored);
        if("Record".equals(target)){
            if(permitted){record();return;}
            page="Meetings";
        }else if(!restored&&("Meetings".equals(target)||"Tasks".equals(target)))page=target;
        render();
    }
    private boolean capture(){String s=RecorderService.getStatus();return startPending||RecorderService.isRecording()||"STARTING".equals(s)||"RECORDING".equals(s);}
    private void render(){if(orb!=null)orb.setActive(false);root=PopUi.column(this);root.setBackgroundColor(PopUi.PAPER);root.setForceDarkAllowed(false);setContentView(root);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=PopUi.column(this);int pad=getResources().getConfiguration().screenWidthDp<=360?18:22;content.setPadding(PopUi.dp(this,pad),PopUi.dp(this,18),PopUi.dp(this,pad),PopUi.dp(this,24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));state=null;timer=null;orb=null;
        if("Record".equals(page)){renderRecorder();return;}
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);View mark=PopUi.brandMark(this);mark.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);header.addView(mark,new LinearLayout.LayoutParams(PopUi.dp(this,28),PopUi.dp(this,28)));TextView brand=PopUi.text(this,"MARGIN",21,true);brand.setTextColor(0xFF203AAF);brand.setLetterSpacing(.12f);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));header.addView(PopUi.sound(this),new LinearLayout.LayoutParams(-2,-2));content.addView(header);
        PopUi.add(content,PopUi.homeTitle(this,"Tasks".equals(page)?"Your tasks":"Your meetings"),16);
        if(error!=null)PopUi.add(content,PopUi.text(this,error,18,false),12);
        if(!indexReady){PopUi.add(content,PopUi.text(this,"Loading saved meetings and validated tasks…",18,false),16);}else if("Tasks".equals(page)){renderTasks();}else renderMeetings();
        Button about=PopUi.button(this,"About MARGIN",false);about.setOnClickListener(v->showAbout());PopUi.add(content,about,20);
        LinearLayout nav=new LinearLayout(this);nav.setPadding(PopUi.dp(this,8),PopUi.dp(this,8),PopUi.dp(this,8),PopUi.dp(this,8));nav.setBackground(PopUi.shape(this,0xFFFFFFFF,0xFFA0B2E2,18));for(String name:new String[]{"Meetings","Record","Tasks"}){String icon="Meetings".equals(name)?"▤":"Record".equals(name)?"●":"✓";Button b=PopUi.button(this,icon+"\n"+name+("Tasks".equals(name)&&indexReady?" ("+open+")":""),page.equals(name));b.setTextSize(16.9f);b.setMinHeight(PopUi.dp(this,65));b.setOnClickListener(v->{if("Record".equals(name))record();else{page=name;render();}});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.setMargins(PopUi.dp(this,16),PopUi.dp(this,10),PopUi.dp(this,16),PopUi.dp(this,10));root.addView(nav,np);
    }
    private void renderMeetings(){PopUi.add(content,PopUi.text(this,"Ready when you are.",21.4f,false),12);Button r=PopUi.button(this,"Record a meeting",true);r.setMinHeight(PopUi.dp(this,64));r.setOnClickListener(v->record());PopUi.add(content,r,21);
        quick("Review notes",drafts+" drafts to check",0xFFFFE18B,()->{for(JSONObject m:meetings)if(m.optJSONObject("_brief")!=null){detail(m,"Summary",false);break;}});quick("View tasks",open+" to follow up",0xFFCFDCFF,()->{page="Tasks";render();});
        if(meetings.isEmpty())PopUi.add(content,PopUi.text(this,"No recordings yet. Record a meeting to keep its audio on this phone.",21.4f,false),20);
        boolean first=true;for(JSONObject m:meetings){if(first){PopUi.add(content,PopUi.text(this,"Latest meeting",18,true),21);first=false;}LinearLayout card=PopUi.card(this,0xFFFFFFFF);PopUi.add(content,card,16);PopUi.add(card,PopUi.text(this,title(m),21.4f,true),0);PopUi.add(card,PopUi.text(this,date(m)+" · "+duration(m.optLong("totalDurationMillis"))+" · "+m.optInt("_open")+" open tasks",18,false),6);PopUi.add(card,PopUi.text(this,m.optJSONObject("_brief")!=null?"Notes need review · Unverified draft":m.optString("status","Needs attention"),18,false),8);Button notes=PopUi.button(this,"View notes",false);notes.setOnClickListener(v->detail(m,"Summary",false));PopUi.add(card,notes,8);Button export=PopUi.button(this,"Export meeting",false);export.setOnClickListener(v->detail(m,"Summary",true));PopUi.add(card,export,8);}
        indexLimitNote();}
    private void quick(String title,String subtitle,int color,Runnable run){LinearLayout card=PopUi.card(this,color);PopUi.add(card,PopUi.text(this,title,20,true),0);PopUi.add(card,PopUi.text(this,subtitle,18,false),4);card.setMinimumHeight(PopUi.dp(this,88));card.setFocusable(true);card.setSoundEffectsEnabled(false);card.setContentDescription(title+", "+subtitle);card.setOnClickListener(v->run.run());PopUi.add(content,card,12);}
    private void renderTasks(){PopUi.add(content,PopUi.text(this,open+" open tasks",21.4f,false),12);for(JSONObject m:meetings){JSONObject brief=m.optJSONObject("_brief");if(brief==null)continue;JSONArray items=brief.optJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(!"actions".equals(item.optString("section")))continue;final int index=i;LinearLayout card=PopUi.card(this,0xFFFFFFFF);PopUi.add(content,card,12);CheckBox done=new CheckBox(this);done.setSoundEffectsEnabled(false);done.setText(item.optString("text"));done.setTextSize(20.3f);done.setTextColor(PopUi.INK);done.setMinHeight(PopUi.dp(this,48));done.setChecked(item.optBoolean("done"));done.setEnabled(!capture());if(done.isChecked())done.setPaintFlags(done.getPaintFlags()|android.graphics.Paint.STRIKE_THRU_TEXT_FLAG);card.addView(done);done.setOnClickListener(v->{done.setChecked(item.optBoolean("done"));saveTask(m,index,null,null,null,!item.optBoolean("done"),done);});PopUi.add(card,PopUi.text(this,item.optBoolean("done")?"Completed":"To do",18,true),4);if(!item.isNull("owner"))PopUi.add(card,PopUi.text(this,"Assigned to: "+item.optString("owner"),18,false),4);if(!item.isNull("date"))PopUi.add(card,PopUi.text(this,"Due: "+item.optString("date"),18,false),4);PopUi.add(card,PopUi.text(this,"Suggested from this meeting. Check the details before you act.",18,false),8);Button from=PopUi.button(this,"From meeting: "+title(m),false);from.setOnClickListener(v->detail(m,"Tasks",false));PopUi.add(card,from,8);Button edit=PopUi.button(this,"Edit",false);edit.setEnabled(!capture());edit.setOnClickListener(v->editTask(card,m,index,item));PopUi.add(card,edit,8);}}if(open==0)PopUi.add(content,PopUi.text(this,"No open tasks in the validated saved briefs.",18,false),16);indexLimitNote();}
    private void editTask(LinearLayout card,JSONObject m,int i,JSONObject item){card.removeAllViews();PopUi.add(card,PopUi.text(this,"Edit task",24,true),0);EditText text=PopUi.input(this,"Task",item.optString("text"),2000),owner=PopUi.input(this,"Assigned to",item.isNull("owner")?"":item.optString("owner"),120),date=PopUi.input(this,"Due",item.isNull("date")?"":item.optString("date"),120);text.setMinLines(3);PopUi.add(card,text,12);PopUi.add(card,owner,12);PopUi.add(card,date,12);Button cancel=PopUi.button(this,"Cancel",false),save=PopUi.button(this,"Save changes",true);cancel.setOnClickListener(v->render());save.setOnClickListener(v->saveTask(m,i,text.getText().toString(),owner.getText().toString(),date.getText().toString(),item.optBoolean("done"),save));PopUi.add(card,cancel,12);PopUi.add(card,save,8);}
    private void saveTask(JSONObject m,int i,String text,String owner,String date,boolean done,View cue){if(text!=null&&text.trim().isEmpty()){Toast.makeText(this,"Enter task text.",Toast.LENGTH_SHORT).show();return;}cue.setEnabled(false);loader.execute(()->{try{JSONObject draft=new JSONObject(m.getJSONObject("_brief").toString()),item=draft.getJSONArray("items").getJSONObject(i);if(text!=null)item.put("text",text).put("owner",owner.trim().isEmpty()?JSONObject.NULL:owner).put("date",date.trim().isEmpty()?JSONObject.NULL:date);item.put("done",done).put("provenance","USER_ENTERED").put("ownerDateProvenance","USER_ENTERED_ONLY");draft.put("provenance","USER_ENTERED");MeetingBriefStore.append(this,new File(new File(getFilesDir(),"sessions"),m.getString("_id")),draft,draft.getString("versionId"),null);handler.post(()->{if(isDestroyed())return;if(visible)PopUi.feedback(cue,"save");Toast.makeText(this,"Task saved as a new revision",Toast.LENGTH_SHORT).show();loadIndex();});}catch(Exception e){handler.post(()->{if(!isDestroyed()){cue.setEnabled(true);Toast.makeText(this,"Task save could not be confirmed. Reload saved notes before retrying.",Toast.LENGTH_LONG).show();}});}});}
    private void indexLimitNote(){if(unavailable>0)PopUi.add(content,PopUi.text(this,unavailable+" meeting briefs unavailable; task counts exclude them.",18,false),12);PopUi.add(content,PopUi.text(this,"Task index covers up to 128 meetings from the 512 most recently changed folders. Counts include validated briefs only.",18,false),12);}
    private void loadIndex(){if(indexBusy)return;indexBusy=true;indexReady=false;loader.execute(()->{ArrayList<JSONObject> rows=new ArrayList<>();int count=0,draftCount=0,failed=0;try{File root=new File(getFilesDir(),"sessions");File[] files=root.listFiles();if(files!=null)Arrays.sort(files,(a,b)->Long.compare(b.lastModified(),a.lastModified()));int scanned=0;if(files!=null)for(File f:files){if(scanned++>=512)break;if(!f.isDirectory()||!f.getName().matches("[a-f0-9-]{36}"))continue;try{if(!UUID.fromString(f.getName()).toString().equals(f.getName())||!f.getAbsoluteFile().equals(f.getCanonicalFile()))throw new IOException();JSONObject m=read(f);m.put("_id",f.getName());rows.add(m);}catch(Exception e){failed++;}}rows.sort((a,b)->Long.compare(b.optLong("startUtc"),a.optLong("startUtc")));while(rows.size()>128)rows.remove(rows.size()-1);for(JSONObject m:rows){try{JSONArray versions=MeetingBriefStore.load(this,new File(root,m.getString("_id")));if(versions.length()>0){JSONObject brief=versions.getJSONObject(versions.length()-1);m.put("_brief",brief);draftCount++;int n=0;JSONArray items=brief.getJSONArray("items");for(int i=0;i<items.length();i++)if("actions".equals(items.getJSONObject(i).optString("section"))&&!items.getJSONObject(i).optBoolean("done"))n++;m.put("_open",n);count+=n;}}catch(Exception e){failed++;}}}catch(Exception e){failed++;}final int n=count,d=draftCount,f=failed;handler.post(()->{if(isDestroyed())return;meetings.clear();meetings.addAll(rows);open=n;drafts=d;unavailable=f;indexReady=true;indexBusy=false;if(!"Record".equals(page))render();});});}
    private static JSONObject read(File f)throws Exception{File meta=new File(f,"session.json");if(!meta.isFile()||meta.length()>262144)throw new IOException();return new JSONObject(new String(new android.util.AtomicFile(meta).readFully(),java.nio.charset.StandardCharsets.UTF_8));}
    private void detail(JSONObject m,String tab,boolean export){startActivity(new Intent(this,MeetingDetailActivity.class).putExtra("sessionId",m.optString("_id")).putExtra("popTab",tab).putExtra("popExport",export));}
    private String title(JSONObject m){String s=m.optString("title");return s.isEmpty()?"Meeting":s;}
    private String date(JSONObject m){long t=m.optLong("startUtc");return t>0?java.text.DateFormat.getDateTimeInstance().format(new Date(t)):"Date unavailable";}
    private String duration(long n){return n>0?String.format(Locale.getDefault(),"%d:%02d",n/60000,n/1000%60):"Duration unavailable";}
    private void record(){page="Record";render();if(!capture()&&!finishing){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},1);else startCapture();}}
    private void startCapture(){captureServiceRequested=false;beforeStart.clear();File[] files=new File(getFilesDir(),"sessions").listFiles();if(files!=null)for(File f:files)beforeStart.add(f.getName());startRequestUtc=System.currentTimeMillis();error=null;recordingId=null;timerBase=-1;startPending=true;PopUi.capturePending=true;PopUi.stopSound();try{PopUi.cue(content);AutoTranscription.requestCapture();waitForTranscriptionBeforeCapture();}catch(Exception e){startPending=false;PopUi.capturePending=false;AutoTranscription.releaseCapture();AutoTranscription.kick(this);error="Recording could not start.";}updateCapture();}
    private boolean captureServiceRequested;
    private void waitForTranscriptionBeforeCapture(){if(captureServiceRequested||RecorderService.isRecording()||!startPending)return;if(!AutoTranscription.quiescent()){if(state!=null)state.setText("Waiting for the current transcript window to save…");handler.postDelayed(this::waitForTranscriptionBeforeCapture,250);return;}try{captureServiceRequested=true;startForegroundService(new Intent(this,RecorderService.class).setAction(RecorderService.ACTION_START));}catch(Exception e){captureServiceRequested=false;startPending=false;PopUi.capturePending=false;AutoTranscription.releaseCapture();AutoTranscription.kick(this);error="Recording could not start.";}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==1){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)startCapture();else{error="Microphone permission is required to record.";page="Meetings";render();}}}
    private void renderRecorder(){Button cancel=PopUi.button(this,"Cancel",false);cancel.setOnClickListener(v->{sheetOpen=true;if(orb!=null)orb.setActive(false);new AlertDialog.Builder(this).setTitle("Finish recording?").setMessage("Finish and keep the recording data on this phone.").setNegativeButton("Keep recording",(d,w)->{sheetOpen=false;updateCapture();}).setPositiveButton("Finish and keep",(d,w)->{sheetOpen=false;finishCapture();}).setOnCancelListener(d->{sheetOpen=false;updateCapture();}).show();});PopUi.add(content,cancel,0);PopUi.add(content,PopUi.text(this,"New meeting",38.7f,true),24);state=PopUi.text(this,"Starting recording…",18,true);PopUi.add(content,state,12);timer=PopUi.text(this,"Elapsed unavailable",55.8f,false);timer.setTextColor(0xFF203BA0);PopUi.add(content,timer,20);orb=new RecordingOrbView(this);content.addView(orb,new LinearLayout.LayoutParams(-1,PopUi.dp(this,230)));Button finish=PopUi.button(this,"Finish recording",true);finish.setOnClickListener(v->finishCapture());PopUi.add(content,finish,16);updateCapture();}
    private void finishCapture(){if(finishing)return;if(startPending&&!captureServiceRequested&&!RecorderService.isRecording()){startPending=false;PopUi.capturePending=false;AutoTranscription.releaseCapture();AutoTranscription.kick(this);page="Meetings";render();return;}if(!capture()){page="Meetings";render();return;}try{finishing=true;startService(new Intent(this,RecorderService.class).setAction(RecorderService.ACTION_STOP));updateCapture();}catch(Exception e){finishing=false;error="Recording could not be stopped. Check its status.";if(state!=null)state.setText(error);}}
    private boolean resolvingSession;
    private void resolveSession(boolean completed){if(resolvingSession)return;resolvingSession=true;loader.execute(()->{JSONObject found=null;try{File[] files=new File(getFilesDir(),"sessions").listFiles();if(files!=null)for(File f:files){if(!f.isDirectory())continue;try{JSONObject m=read(f);boolean candidate=recordingId!=null?recordingId.equals(f.getName()):startRequestUtc>0?!beforeStart.contains(f.getName())&&m.optLong("startUtc")>=startRequestUtc:"ACTIVE".equals(m.optString("status"));if(candidate&&(!completed||"COMPLETED".equals(m.optString("status")))){m.put("_id",f.getName());found=m;break;}}catch(Exception ignored){}}}catch(Exception ignored){}final JSONObject result=found;handler.post(()->{resolvingSession=false;if(isDestroyed())return;if(result!=null){recordingId=result.optString("_id");if(timerBase<0&&result.optLong("startUtc")>0)timerBase=SystemClock.elapsedRealtime()-Math.max(0,System.currentTimeMillis()-result.optLong("startUtc"));if(completed){finishing=false;page="Meetings";PopUi.capturePending=false;if(visible)PopUi.feedback(content,"finish");detail(result,"Transcript",false);}}else if(completed){finishing=false;error="Capture stopped; no completed new meeting was found. Check saved meetings.";page="Meetings";loadIndex();render();}});});}
    private void updateCapture(){String s=RecorderService.getStatus();if(("STOPPED".equals(s)&&!startPending)||"ERROR".equals(s))PopUi.capturePending=false;if("STARTING".equals(s)||"RECORDING".equals(s))startPending=false;if("ERROR".equals(s)){startPending=false;finishing=false;error="Recording needs attention. Saved data is retained.";}if(finishing&&"STOPPED".equals(s)&&!RecorderService.isRecording()){startPending=false;resolveSession(true);}else if("Record".equals(page)&&capture()&&recordingId==null)resolveSession(false);if(state!=null)state.setText(error!=null?error:finishing?"Finishing and saving audio…":"RECORDING".equals(s)?"● Recording":"STARTING".equals(s)||startPending?"Starting recording…":"Capture stopped");if(timer!=null)timer.setText(timerBase>=0?duration(Math.max(1,SystemClock.elapsedRealtime()-timerBase)):"Elapsed unavailable");if(orb!=null)orb.setActive(visible&&!sheetOpen&&"Record".equals(page)&&!finishing&&"RECORDING".equals(s));}
    static String edge0Availability(){return "Optional Edge0 is not installed or validated.";}
    private void showAbout(){String version="Build identity unavailable";try{android.content.pm.PackageInfo p=getPackageManager().getPackageInfo(getPackageName(),0);version=p.versionName+" · build "+p.getLongVersionCode();}catch(Exception ignored){}new AlertDialog.Builder(this).setTitle("MARGIN").setMessage(version+"\nPrivate local meeting notebook. AI drafts are unverified and use partial sources; source fallback is available. Automatic speakers and summaries remain unaccepted. Word timings unavailable. Controlled endurance and battery checks are deferred to field validation. "+edge0Availability()).setPositiveButton("Done",null).show();}
    @Override protected void onResume(){super.onResume();visible=true;if(startPending&&AutoTranscription.captureRequested())waitForTranscriptionBeforeCapture();if(!capture()&&!AutoTranscription.captureRequested()) { AutoTranscription.kick(this); }loadIndex();handler.removeCallbacks(poll);handler.post(poll);}
    @Override protected void onPause(){visible=false;PopUi.stopSound();handler.removeCallbacks(poll);if(orb!=null)orb.setActive(false);super.onPause();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);loader.shutdownNow();super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle b){b.putString("page",page);b.putBoolean("finishing",finishing);b.putBoolean("startPending",startPending);b.putLong("startRequestUtc",startRequestUtc);b.putString("recordingId",recordingId);b.putStringArrayList("beforeStart",new ArrayList<>(beforeStart));super.onSaveInstanceState(b);}
    @Override public void onBackPressed(){if("Record".equals(page)&&capture()){sheetOpen=true;if(orb!=null)orb.setActive(false);new AlertDialog.Builder(this).setTitle("Keep recording?").setMessage("Recording continues when you leave this screen.").setNegativeButton("Stay",(d,w)->{sheetOpen=false;updateCapture();}).setPositiveButton("Meetings",(d,w)->{sheetOpen=false;page="Meetings";render();}).setOnCancelListener(d->{sheetOpen=false;updateCapture();}).show();}else if(!"Meetings".equals(page)){page="Meetings";render();}else super.onBackPressed();}
}
